-- All fixture companies, grants, records and audit entries are rolled back.
BEGIN;
DO $test$
DECLARE cid uuid:=gen_random_uuid();actor uuid;product uuid;customer uuid;day uuid;sale uuid;tab uuid;receipt uuid;payable uuid;payment uuid;service uuid;
 request uuid:=gen_random_uuid();close_request uuid:=gen_random_uuid();args jsonb;close_args jsonb;result jsonb;state jsonb;account uuid;rev bigint;
BEGIN
 SELECT id INTO actor FROM auth.users ORDER BY created_at LIMIT 1;
 IF actor IS NULL THEN RAISE EXCEPTION 'Fixture requires an existing Auth identity';END IF;
 INSERT INTO public.tectria_companies(id,name) VALUES(cid,'Fixture Nexo Mobile rollback');
 INSERT INTO public.tectria_memberships(company_id,user_id,role) VALUES(cid,actor,'owner');
 INSERT INTO public.tectria_entitlements(company_id,product_code) VALUES(cid,'nexo_mobile');
 INSERT INTO public.tectria_user_product_access(company_id,user_id,product_code,role) VALUES(cid,actor,'nexo_mobile','owner');
 PERFORM set_config('request.jwt.claim.sub',actor::text,true);
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',actor,'role','authenticated')::text,true);
 ASSERT NOT has_function_privilege('anon','public.nexo_mobile_workspace_command(uuid,uuid,text,jsonb)','EXECUTE');
 ASSERT NOT has_table_privilege('authenticated','tectria_private.nexo_mobile_workspaces','SELECT');
 ASSERT NOT has_function_privilege('authenticated','tectria_private.nm_int(jsonb,bigint,bigint)','EXECUTE');
 ASSERT public.nexo_mobile_workspace_state(cid)->>'source'='nexo-mobile-cloud';
 PERFORM public.nexo_mobile_workspace_command(cid,gen_random_uuid(),'configure','{"segment":"restaurant"}');
 result:=public.nexo_mobile_workspace_command(cid,gen_random_uuid(),'product_save','{"name":"Produto de teste","code":"FIXTURE","unit":"un","priceCents":1000,"costCents":200,"minimumMills":2000,"tracked":true}');product:=(result->>'id')::uuid;
 PERFORM public.nexo_mobile_workspace_command(cid,gen_random_uuid(),'stock_move',jsonb_build_object('productId',product,'qtyMills',10000,'reason','Entrada de teste'));
 result:=public.nexo_mobile_workspace_command(cid,gen_random_uuid(),'contact_save','{"name":"Cliente de teste","kind":"both","phone":""}');customer:=(result->>'id')::uuid;
 result:=public.nexo_mobile_workspace_command(cid,gen_random_uuid(),'day_open','{}');day:=(result->>'id')::uuid;
 args:=jsonb_build_object('dayId',day,'items',jsonb_build_array(jsonb_build_object('productId',product,'qtyMills',2000,'priceCents',1000)),'totalCents',2000,'paidCents',500,'method','pix','contactId',customer,'installments',jsonb_build_array(jsonb_build_object('due',current_date,'amountCents',750),jsonb_build_object('due',current_date+30,'amountCents',750)));
 result:=public.nexo_mobile_workspace_command(cid,request,'sale',args);sale:=(result->>'id')::uuid;
 ASSERT public.nexo_mobile_workspace_command(cid,request,'sale',args)->>'replayed'='true';
 state:=public.nexo_mobile_workspace_state(cid)->'document';
 ASSERT state->'products'->0->>'balanceMills'='8000';ASSERT jsonb_array_length(state->'sales')=1;
 BEGIN PERFORM public.nexo_mobile_workspace_command(cid,request,'sale',args||'{"paidCents":0}');RAISE EXCEPTION 'Divergent replay accepted';EXCEPTION WHEN unique_violation THEN NULL;END;
 account:=(state->'sales'->0->'accounts'->1->>'id')::uuid;
 result:=public.nexo_mobile_workspace_command(cid,gen_random_uuid(),'receive',jsonb_build_object('dayId',day,'saleId',sale,'accountId',account,'amountCents',250,'method','cash'));receipt:=(result->>'id')::uuid;
 PERFORM public.nexo_mobile_workspace_command(cid,gen_random_uuid(),'receipt_reverse',jsonb_build_object('dayId',day,'id',receipt,'reason','Estorno de teste'));
 state:=public.nexo_mobile_workspace_state(cid)->'document';ASSERT state->'sales'->0->'accounts'->1->>'paidCents'='0';ASSERT state->'products'->0->>'balanceMills'='8000';
 args:=jsonb_set(jsonb_set(jsonb_set(args,'{items,0,qtyMills}','1000'),'{totalCents}','1000'),'{paidCents}','0')||jsonb_build_object('installments',jsonb_build_array(jsonb_build_object('due',current_date,'amountCents',1000)));
 PERFORM public.nexo_mobile_workspace_command(cid,gen_random_uuid(),'sale',args);
 BEGIN PERFORM public.nexo_mobile_workspace_command(cid,gen_random_uuid(),'sale',jsonb_set(args,'{items,0,qtyMills}','1'));RAISE EXCEPTION 'Fractional unit accepted';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 BEGIN PERFORM public.nexo_mobile_workspace_command(cid,gen_random_uuid(),'sale',jsonb_set(args,'{items,0,priceCents}','999'));RAISE EXCEPTION 'Stale price accepted';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 BEGIN PERFORM public.nexo_mobile_workspace_command(cid,gen_random_uuid(),'sale',jsonb_set(args,'{items,0,qtyMills}','100000'));RAISE EXCEPTION 'Overselling accepted';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 result:=public.nexo_mobile_workspace_command(cid,gen_random_uuid(),'payable_create',jsonb_build_object('description','Despesa de teste','amountCents',1000,'due',current_date,'contactId',customer));payable:=(result->>'id')::uuid;
 result:=public.nexo_mobile_workspace_command(cid,gen_random_uuid(),'pay',jsonb_build_object('dayId',day,'payableId',payable,'amountCents',200,'method','pix'));payment:=(result->>'id')::uuid;
 PERFORM public.nexo_mobile_workspace_command(cid,gen_random_uuid(),'payment_reverse',jsonb_build_object('dayId',day,'id',payment,'reason','Estorno de teste'));
 ASSERT public.nexo_mobile_workspace_state(cid)->'document'->'payables'->0->>'paidCents'='0';
 result:=public.nexo_mobile_workspace_command(cid,gen_random_uuid(),'table_save',jsonb_build_object('name','Mesa teste','staff','Garçom de teste','items',args->'items'));tab:=(result->>'id')::uuid;
 BEGIN PERFORM public.nexo_mobile_workspace_command(cid,gen_random_uuid(),'day_close',jsonb_build_object('dayId',day));RAISE EXCEPTION 'Open tab ignored';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 close_args:=jsonb_build_object('tableId',tab,'tableVersion',1,'dayId',day,'totalCents',1000,'paidCents',1000,'method','card','receiptParts',jsonb_build_array(jsonb_build_object('amountCents',400,'method','pix','person','Pessoa A'),jsonb_build_object('amountCents',600,'method','card','person','Pessoa B')),'installments','[]'::jsonb);
 PERFORM public.nexo_mobile_workspace_command(cid,close_request,'table_close',close_args);
 ASSERT public.nexo_mobile_workspace_command(cid,close_request,'table_close',close_args)->>'replayed'='true';
 state:=public.nexo_mobile_workspace_state(cid)->'document';ASSERT state->'products'->0->>'balanceMills'='6000';
 PERFORM public.nexo_mobile_workspace_command(cid,gen_random_uuid(),'sale_cancel',jsonb_build_object('dayId',day,'id',sale,'reason','Cancelamento de teste'));
 ASSERT public.nexo_mobile_workspace_state(cid)->'document'->'products'->0->>'balanceMills'='8000';
 result:=public.nexo_mobile_workspace_command(cid,gen_random_uuid(),'product_save','{"name":"Serviço de teste","code":"SERVICE","unit":"un","priceCents":500,"costCents":0,"minimumMills":0,"tracked":false}');service:=(result->>'id')::uuid;
 result:=public.nexo_mobile_workspace_command(cid,gen_random_uuid(),'sale',jsonb_build_object('dayId',day,'items',jsonb_build_array(jsonb_build_object('productId',service,'qtyMills',1000,'priceCents',500)),'totalCents',500,'paidCents',500,'method','pix','installments','[]'::jsonb));
 PERFORM public.nexo_mobile_workspace_command(cid,gen_random_uuid(),'sale_cancel',jsonb_build_object('dayId',day,'id',result->>'id','reason','Cancelamento de serviço'));
 ASSERT public.nexo_mobile_workspace_state(cid)->'document'->'products'->1->>'balanceMills'='0';
 BEGIN PERFORM public.nexo_mobile_workspace_command(cid,gen_random_uuid(),'stock_move',jsonb_build_object('productId',product,'qtyMills',true,'reason','Invalid bool'));RAISE EXCEPTION 'Boolean quantity accepted';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 BEGIN PERFORM public.nexo_mobile_workspace_command(cid,gen_random_uuid(),'day_close','{}');RAISE EXCEPTION 'Missing day accepted';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 PERFORM public.nexo_mobile_workspace_command(cid,gen_random_uuid(),'day_close',jsonb_build_object('dayId',day));
 BEGIN PERFORM public.nexo_mobile_workspace_command(cid,gen_random_uuid(),'sale',args);RAISE EXCEPTION 'Closed day accepted';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 UPDATE public.tectria_user_product_access SET role='viewer' WHERE company_id=cid AND product_code='nexo_mobile';
 ASSERT public.nexo_mobile_workspace_state(cid)->>'canWrite'='false';
 BEGIN PERFORM public.nexo_mobile_workspace_command(cid,gen_random_uuid(),'day_open','{}');RAISE EXCEPTION 'Viewer write accepted';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN PERFORM public.nexo_mobile_workspace_state(gen_random_uuid());RAISE EXCEPTION 'Other company accepted';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 UPDATE public.tectria_entitlements SET suspended=true WHERE company_id=cid AND product_code='nexo_mobile';
 BEGIN PERFORM public.nexo_mobile_workspace_state(cid);RAISE EXCEPTION 'Suspended access accepted';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 PERFORM set_config('request.jwt.claim.sub','',true);PERFORM set_config('request.jwt.claims','{}',true);
 BEGIN PERFORM public.nexo_mobile_workspace_state(cid);RAISE EXCEPTION 'Anonymous accepted';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
END $test$;
ROLLBACK;
SELECT 'Nexo Mobile: transactional fixture and access checks passed; all fixture writes rolled back.' AS result;
